<?php
 namespace QQWorld\Framework\Code\Generator; abstract class EntityAbstract { const ENTITY_TYPE = 'abstract'; private $_errors = []; private $_sourceClassName; private $_resultClassName; private $_ioObject; protected $_classGenerator; private $definedClasses; public function __construct( $sourceClassName = null, $resultClassName = null, Io $ioObject = null, \QQWorld\Framework\Code\Generator\CodeGeneratorInterface $classGenerator = null, DefinedClasses $definedClasses = null ) { if ($ioObject) { $this->_ioObject = $ioObject; } else { $this->_ioObject = new Io(new \QQWorld\Framework\Filesystem\Driver\File()); } if ($classGenerator) { $this->_classGenerator = $classGenerator; } else { $this->_classGenerator = new ClassGenerator(); } if ($definedClasses) { $this->definedClasses = $definedClasses; } else { $this->definedClasses = new DefinedClasses(); } $this->_sourceClassName = $this->_getFullyQualifiedClassName($sourceClassName); if ($resultClassName) { $this->_resultClassName = $this->_getFullyQualifiedClassName($resultClassName); } elseif ($this->_sourceClassName) { $this->_resultClassName = $this->_getDefaultResultClassName($this->_sourceClassName); } } public function generate() { try { if ($this->_validateData()) { $sourceCode = $this->_generateCode(); if ($sourceCode) { $fileName = $this->_ioObject->generateResultFileName($this->_getResultClassName()); $this->_ioObject->writeResultFile($fileName, $sourceCode); return $fileName; } else { $this->_addError('Can\'t generate source code.'); } } } catch (\Exception $e) { $this->_addError($e->getMessage()); } return false; } public function getErrors() { return $this->_errors; } public function getSourceClassName() { return $this->_sourceClassName; } public function getSourceClassNameWithoutNamespace() { $parts = explode('\\', ltrim($this->getSourceClassName(), '\\')); return end($parts); } protected function _getFullyQualifiedClassName($className) { $className = ltrim($className, '\\'); return $className ? '\\' . $className : ''; } protected function _getResultClassName() { return $this->_resultClassName; } protected function _getDefaultResultClassName($modelClassName) { return $modelClassName . ucfirst(static::ENTITY_TYPE); } protected function _getClassProperties() { $objectManager = [ 'name' => '_objectManager', 'visibility' => 'protected', 'docblock' => [ 'shortDescription' => 'Object Manager instance', 'tags' => [['name' => 'var', 'description' => '\\' . \QQWorld\Framework\ObjectManagerInterface::class]], ], ]; return [$objectManager]; } abstract protected function _getDefaultConstructorDefinition(); abstract protected function _getClassMethods(); protected function _generateCode() { $this->_classGenerator->setName($this->_getResultClassName()) ->addProperties($this->_getClassProperties()) ->addMethods($this->_getClassMethods()) ->setClassDocBlock($this->_getClassDocBlock()); return $this->_getGeneratedCode(); } protected function _addError($message) { $this->_errors[] = $message; return $this; } protected function _validateData() { $sourceClassName = $this->getSourceClassName(); $resultClassName = $this->_getResultClassName(); $resultDir = $this->_ioObject->getResultFileDirectory($resultClassName); if (!$this->definedClasses->isClassLoadable($sourceClassName)) { $this->_addError('Source class ' . $sourceClassName . ' doesn\'t exist.'); return false; } elseif ( !$this->_ioObject->makeResultFileDirectory($resultClassName) && !$this->_ioObject->fileExists($resultDir) ) { $this->_addError('Can\'t create directory ' . $resultDir . '.'); return false; } return true; } protected function _getClassDocBlock() { $description = ucfirst(static::ENTITY_TYPE) . ' class for @see ' . $this->getSourceClassName(); return ['shortDescription' => $description]; } protected function _getGeneratedCode() { $sourceCode = $this->_classGenerator->generate(); return $this->_fixCodeStyle($sourceCode); } protected function _fixCodeStyle($sourceCode) { $sourceCode = str_replace(' array (', ' array(', $sourceCode); $sourceCode = preg_replace("/{\n{2,}/m", "{\n", $sourceCode); $sourceCode = preg_replace("/\n{2,}}/m", "\n}", $sourceCode); return $sourceCode; } protected function _getNullDefaultValue() { $value = new \Zend\Code\Generator\ValueGenerator(null, \Zend\Code\Generator\ValueGenerator::TYPE_NULL); return $value; } protected function _getMethodParameterInfo(\ReflectionParameter $parameter) { $parameterInfo = [ 'name' => $parameter->getName(), 'passedByReference' => $parameter->isPassedByReference(), 'type' => $parameter->getType(), 'variadic' => $parameter->isVariadic() ]; if ($parameter->isArray()) { $parameterInfo['type'] = 'array'; } elseif ($parameter->getClass()) { $parameterInfo['type'] = $this->_getFullyQualifiedClassName($parameter->getClass()->getName()); } elseif ($parameter->isCallable()) { $parameterInfo['type'] = 'callable'; } if ($parameter->isOptional() && $parameter->isDefaultValueAvailable()) { $defaultValue = $parameter->getDefaultValue(); if (is_string($defaultValue)) { $parameterInfo['defaultValue'] = $parameter->getDefaultValue(); } elseif ($defaultValue === null) { $parameterInfo['defaultValue'] = $this->_getNullDefaultValue(); } else { $parameterInfo['defaultValue'] = $defaultValue; } } return $parameterInfo; } public function init($sourceClassName, $resultClassName) { $this->_sourceClassName = $sourceClassName; $this->_resultClassName = $resultClassName; } } 